types.SM.IntervalComposition.consecutive_conta:
SM.IntervalComposition.consecutive_contained_in_part {n : ℕ} [NeZero n] {I : SM.BoundaryInterval n}
  (π : SM.IntervalComposition I) (T : SM.BoundaryCutSet I) (hπ : π.cutSet.cuts ⊆ T.cuts) (J : SM.BoundaryInterval n)
  (hJ : T.Consecutive J) : ∃ k, (π.part k).left ≤ J.left ∧ J.right ≤ (π.part k).right

types.SM.IntervalComposition.containing_part_u:
SM.IntervalComposition.containing_part_unique {n : ℕ} [NeZero n] {I : SM.BoundaryInterval n}
  (π : SM.IntervalComposition I) (J : SM.BoundaryInterval n) {k l : Fin π.parts}
  (hk : (π.part k).left ≤ J.left ∧ J.right ≤ (π.part k).right)
  (hl : (π.part l).left ≤ J.left ∧ J.right ≤ (π.part l).right) : k = l

types.SM.IntervalComposition.nearTriple_consec:
SM.IntervalComposition.nearTriple_consecutive {n : ℕ} [NeZero n] {I : SM.BoundaryInterval n}
  (π : SM.IntervalComposition I) (k : Fin (π.parts - 1)) :
  π.cutSet.Consecutive (π.nearTriple k).leftInterval ∧ π.cutSet.Consecutive (π.nearTriple k).rightInterval

types.SM.IntervalComposition.inner_child_conse:
SM.IntervalComposition.inner_child_consecutive {n : ℕ} [NeZero n] {I : SM.BoundaryInterval n}
  (π : SM.IntervalComposition I) (T : SM.RefiningCutSet π) (k : Fin π.parts) (j : Fin (π.refinementInner T k).parts) :
  (↑T).Consecutive ((π.refinementInner T k).part j)

types.SM.IntervalComposition.exists_refined_ch:
SM.IntervalComposition.exists_refined_child {n : ℕ} [NeZero n] {I : SM.BoundaryInterval n}
  (π : SM.IntervalComposition I) (T : SM.RefiningCutSet π) (k : Fin π.parts) (j : Fin (π.refinementInner T k).parts) :
  ∃ r, (↑T).toComposition.part r = (π.refinementInner T k).part j

types.SM.IntervalComposition.refinedChildIndex:
SM.IntervalComposition.refinedChildIndex_part {n : ℕ} [NeZero n] {I : SM.BoundaryInterval n}
  (π : SM.IntervalComposition I) (T : SM.RefiningCutSet π) (a : (k : Fin π.parts) × Fin (π.refinementInner T k).parts) :
  (↑T).toComposition.part (π.refinedChildIndex T a) = (π.refinementInner T a.fst).part a.snd

types.SM.IntervalComposition.refinedChildrenEq:
SM.IntervalComposition.refinedChildrenEquiv {n : ℕ} [NeZero n] {I : SM.BoundaryInterval n}
  (π : SM.IntervalComposition I) (T : SM.RefiningCutSet π) :
  (k : Fin π.parts) × Fin (π.refinementInner T k).parts ≃ Fin (↑T).toComposition.parts

types.SM.IntervalComposition.prod_refined_chil:
SM.IntervalComposition.prod_refined_children.{u_1} {n : ℕ} [NeZero n] {I : SM.BoundaryInterval n} {R : Type u_1}
  [CommMonoid R] (π : SM.IntervalComposition I) (T : SM.RefiningCutSet π) (X : SM.BoundaryInterval n → R) :
  ∏ k, ∏ j, X ((π.refinementInner T k).part j) = ∏ r, X ((↑T).toComposition.part r)

types.SM.IntervalComposition.refinementInner_f:
SM.IntervalComposition.refinementInner_flatten {n : ℕ} [NeZero n] {I : SM.BoundaryInterval n}
  (π : SM.IntervalComposition I) (σ : (k : Fin π.parts) → SM.IntervalComposition (π.part k)) (k : Fin π.parts) :
  π.refinementInner (π.flattenRefinement fun k => (σ k).cutSet) k = σ k

types.SM.IntervalComposition.position_mem_inde:
SM.IntervalComposition.position_mem_indexMarks {n : ℕ} [NeZero n] {I : SM.BoundaryInterval n}
  (π : SM.IntervalComposition I) (s : Finset (Fin (π.parts - 1))) (k : Fin (π.parts - 1)) :
  π.interiorPosition k ∈ ↑(π.indexMarks s) ↔ k ∈ s

types.SM.IntervalComposition.prod_indexMarks:
SM.IntervalComposition.prod_indexMarks.{u_1} {n : ℕ} [NeZero n] {I : SM.BoundaryInterval n} {R : Type u_1}
  [CommMonoid R] (π : SM.IntervalComposition I) (s : Finset (Fin (π.parts - 1))) (f : Fin n → R) :
  ∏ k ∈ s, f (π.interiorPosition k) = ∏ x ∈ ↑(π.indexMarks s), f x

types.SM.IntervalComposition.prod_markIndices:
SM.IntervalComposition.prod_markIndices.{u_1} {n : ℕ} [NeZero n] {I : SM.BoundaryInterval n} {R : Type u_1}
  [CommMonoid R] (π : SM.IntervalComposition I) (m : SM.MarkedCuts π.cutSet) (f : Fin n → R) :
  ∏ k ∈ π.markIndices m, f (π.interiorPosition k) = ∏ x ∈ ↑m, f x

types.SM.IntervalComposition.refinedInteriorIn:
SM.IntervalComposition.refinedInteriorIndex {n : ℕ} [NeZero n] {I : SM.BoundaryInterval n}
  (π : SM.IntervalComposition I) (T : SM.RefiningCutSet π)
  (a : (k : Fin π.parts) × Fin ((π.refinementInner T k).parts - 1)) : Fin ((↑T).toComposition.parts - 1)

types.SM.IntervalComposition.refinedUnmarkedIn:
SM.IntervalComposition.refinedUnmarkedIndex {n : ℕ} [NeZero n] {I : SM.BoundaryInterval n}
  (π : SM.IntervalComposition I) (T : SM.RefiningCutSet π)
  (a : (k : Fin π.parts) × Fin ((π.refinementInner T k).parts - 1)) : π.RefinementUnmarked T

types.SM.IntervalComposition.refinedUnmarkedEq:
SM.IntervalComposition.refinedUnmarkedEquiv {n : ℕ} [NeZero n] {I : SM.BoundaryInterval n}
  (π : SM.IntervalComposition I) (T : SM.RefiningCutSet π) :
  (k : Fin π.parts) × Fin ((π.refinementInner T k).parts - 1) ≃ π.RefinementUnmarked T

types.SM.IntervalComposition.prod_inner_nearTr:
SM.IntervalComposition.prod_inner_nearTriples.{u_1} {n : ℕ} [NeZero n] {I : SM.BoundaryInterval n} {R : Type u_1}
  [CommMonoid R] (π : SM.IntervalComposition I) (T : SM.RefiningCutSet π) (f : SM.IncreasingBoundaryTriple n → R) :
  ∏ k, ∏ j, f ((π.refinementInner T k).nearTriple j) = ∏ r, f ((↑T).toComposition.nearTriple ↑r)

types.SM.IntervalComposition.outerPosition_in_:
SM.IntervalComposition.outerPosition_in_refinement {n : ℕ} [NeZero n] {I : SM.BoundaryInterval n}
  (π : SM.IntervalComposition I) (T : SM.RefiningCutSet π) (j : Fin (π.parts - 1)) :
  π.interiorPosition j ∈ ↑(↑T).interior

types.SM.IntervalComposition.refinedOuterIndex:
SM.IntervalComposition.refinedOuterIndex_position {n : ℕ} [NeZero n] {I : SM.BoundaryInterval n}
  (π : SM.IntervalComposition I) (T : SM.RefiningCutSet π) (j : Fin (π.parts - 1)) :
  (↑T).toComposition.interiorPosition (π.refinedOuterIndex T j) = π.interiorPosition j

types.SM.IntervalComposition.outer_farTriple_t:
SM.IntervalComposition.outer_farTriple_transport {n : ℕ} [NeZero n] {I : SM.BoundaryInterval n}
  (π : SM.IntervalComposition I) (T : SM.RefiningCutSet π) (j : Fin (π.parts - 1)) :
  (↑T).toComposition.farTriple (π.refinedOuterIndex T j) = π.farTriple j

types.SM.IntervalComposition.prod_outer_farTri:
SM.IntervalComposition.prod_outer_farTriples.{u_1} {n : ℕ} [NeZero n] {I : SM.BoundaryInterval n} {R : Type u_1}
  [CommMonoid R] (π : SM.IntervalComposition I) (T : SM.RefiningCutSet π) (f : SM.IncreasingBoundaryTriple n → R) :
  ∏ j, f (π.farTriple j) = ∏ r, f ((↑T).toComposition.farTriple ↑r)

types.SM.IntervalComposition.mem_refinementMar:
SM.IntervalComposition.mem_refinementMarkIndices {n : ℕ} [NeZero n] {I : SM.BoundaryInterval n}
  (π : SM.IntervalComposition I) (T : SM.RefiningCutSet π) (r : Fin ((↑T).toComposition.parts - 1)) :
  r ∈ π.refinementMarkIndices T ↔ (↑T).toComposition.interiorPosition r ∈ π.cutSet.cuts

types.SM.IntervalComposition.prod_refinementMa:
SM.IntervalComposition.prod_refinementMarked.{u_1} {n : ℕ} [NeZero n] {I : SM.BoundaryInterval n} {R : Type u_1}
  [CommMonoid R] (π : SM.IntervalComposition I) (T : SM.RefiningCutSet π) (f : Fin ((↑T).toComposition.parts - 1) → R) :
  ∏ r, f ↑r = ∏ r ∈ π.refinementMarkIndices T, f r

types.SM.IntervalComposition.prod_refinementUn:
SM.IntervalComposition.prod_refinementUnmarked.{u_1} {n : ℕ} [NeZero n] {I : SM.BoundaryInterval n} {R : Type u_1}
  [CommMonoid R] (π : SM.IntervalComposition I) (T : SM.RefiningCutSet π) (f : Fin ((↑T).toComposition.parts - 1) → R) :
  ∏ r, f ↑r = ∏ r ∈ (π.refinementMarkIndices T)ᶜ, f r

types.SM.IntervalComposition.nearFarWeight_nea:
SM.IntervalComposition.nearFarWeight_near_only.{u_1} {n : ℕ} [NeZero n] {I : SM.BoundaryInterval n} {R : Type u_1}
  [CommRing R] [Invertible 2] (π : SM.IntervalComposition I) (D : SM.TripleArray n R) :
  π.nearFarWeight D 0 = ∏ r, D (π.nearTriple r) * ⅟2

types.SM.IntervalComposition.nearFarWeight_far:
SM.IntervalComposition.nearFarWeight_far_only.{u_1} {n : ℕ} [NeZero n] {I : SM.BoundaryInterval n} {R : Type u_1}
  [CommRing R] [Invertible 2] (π : SM.IntervalComposition I) (H : SM.TripleArray n R) :
  π.nearFarWeight 0 H = ∏ r, -H (π.farTriple r) * ⅟2

types.SM.IntervalComposition.nestedMarkedCutEq:
SM.IntervalComposition.nestedMarkedCutEquiv_marks {n : ℕ} [NeZero n] {I : SM.BoundaryInterval n}
  (π : SM.IntervalComposition I) (σ : (k : Fin π.parts) → SM.IntervalComposition (π.part k)) :
  ↑((SM.IntervalComposition.nestedMarkedCutEquiv I) ⟨π, σ⟩).snd = ↑π.cutSet.interior

types.SM.IntervalComposition.sum_markedSummand:
SM.IntervalComposition.sum_markedSummand.{u_1} {n : ℕ} [NeZero n] {I : SM.BoundaryInterval n} {R : Type u_1}
  [CommRing R] [Invertible 2] (D H : SM.TripleArray n R) (X : SM.IntervalArray n R) (ρ : SM.IntervalComposition I) :
  ∑ m, SM.IntervalComposition.markedSummand D H X ρ m = ρ.nearFarWeight D H * ∏ j, X (ρ.part j)
